import{expectFunction,expectObjectRecord,expectOnlyKnownKeys}from"#internal/authored-module.js";import{toErrorMessage}from"#shared/errors.js";import{ResolveAgentError,loadResolvedModuleExport}from"#runtime/resolve-helpers.js";async function resolveDynamicSubagentDefinition(e){try{let t=await loadResolvedModuleExport({definition:e.definition,kindLabel:`dynamic subagent`,moduleMap:e.moduleMap,nodeId:e.nodeId});return normalizeResolvedDynamicSubagentDefinition(e.definition,t)}catch(t){throw t instanceof ResolveAgentError?t:new ResolveAgentError(`Failed to resolve dynamic subagent from "${e.definition.logicalPath}": ${toErrorMessage(t)}`,{logicalPath:e.definition.logicalPath,sourceId:e.definition.sourceId})}}function normalizeResolvedDynamicSubagentDefinition(n,r){let i=`Expected the dynamic subagent export "${n.exportName??`default`}" from "${n.logicalPath}" to provide defineDynamic({ events }).`,a=expectObjectRecord(r,i);if(expectOnlyKnownKeys(a,[`build`,`events`,`kind`],i),a.kind!==`eve:dynamic`)throw Error(i);let o=expectObjectRecord(a.events,i),s={};for(let t of n.eventNames)s[t]=expectFunction(o[t],i);return{eventNames:[...n.eventNames],events:s,exportName:n.exportName,logicalPath:n.logicalPath,sourceId:n.sourceId,sourceKind:`module`}}export{normalizeResolvedDynamicSubagentDefinition,resolveDynamicSubagentDefinition};